#include <iostream>
#include <limits>
#include <string>

int main() {
    int nuevoNumero = 0;
    const bool numeroLeido = static_cast<bool>(std::cin >> nuevoNumero);

    if (std::cin.bad()) {
        return 2;
    }
    int numero = 42;
    std::string registro = "base";
    bool aceptado = false;

    bool saltoConsumido = false;
    if (numeroLeido) {
        char separador = '?';
        if (std::cin.get(separador)) {
            if (separador == ';') {
                char candidato[6]{};

                std::cin.getline(candidato, 6);

                saltoConsumido = !std::cin.fail() && !std::cin.eof();
                if (saltoConsumido) {
                    numero = nuevoNumero;
                    registro = candidato;
                    aceptado = true;
                }
            } else {
                saltoConsumido = separador == '\n';
            }
        }
    }
    if (std::cin.bad()) {
        return 2;
    }
    if (!aceptado && !saltoConsumido && !std::cin.eof()) {
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    }

    std::string siguiente;
    const bool haySiguiente = static_cast<bool>(std::getline(std::cin, siguiente));

    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "Registro=" << numero << ":[" << registro << "]\n";
    std::cout << "Siguiente=" << haySiguiente << ":[" << siguiente << "]\n";

    return 0;
}

